package com.medical.ui.panels;
import com.medical.ui.dialogs.VisiteDialog;import com.medical.ui.models.*;import com.medical.ui.utils.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.Arrays;
public class VisitePanel extends JPanel{private final ApiClient api;private final VisiteTableModel model=new VisiteTableModel();private final JTable table=new JTable(model);private final JLabel status;public VisitePanel(ApiClient a,JLabel s){api=a;status=s;setLayout(new BorderLayout(12,12));setBorder(new EmptyBorder(4,4,4,4));add(toolbar(),BorderLayout.NORTH);UiStyle.table(table);table.setAutoCreateRowSorter(true);RowActionCell.install(table,5,this::editRow,this::deleteRow);add(UiStyle.card(new JScrollPane(table)),BorderLayout.CENTER);refresh();}
private JToolBar toolbar(){JToolBar b=new JToolBar();b.setFloatable(false);b.setBorder(new EmptyBorder(4,0,4,0));b.add(UiStyle.title("Visites"));b.add(Box.createHorizontalStrut(18));JButton a=new JButton("＋  Programmer une visite"),r=new JButton("↻  Actualiser");UiStyle.primaryButton(a);UiStyle.secondaryButton(r);a.addActionListener(e->add());r.addActionListener(e->refresh());b.add(a);b.add(Box.createHorizontalStrut(8));b.add(r);return b;}
private void refresh(){new SwingWorker<Visite[],Void>(){protected Visite[]doInBackground()throws Exception{return api.get("/api/visites",Visite[].class);}protected void done(){try{model.setData(Arrays.asList(get()));status.setText("  "+model.getRowCount()+" visite(s) affichée(s)");}catch(Exception e){error(e);}}}.execute();}
private void add(){VisiteDialog d=new VisiteDialog(SwingUtilities.getWindowAncestor(this),null);d.setVisible(true);if(!d.isOk())return;run(()->api.post("/api/visites",new Visite(d.med(),d.pat(),d.date(),"",""),Visite.class));}private void editRow(int row){Visite o=model.getAt(row);VisiteDialog d=new VisiteDialog(SwingUtilities.getWindowAncestor(this),o);d.setVisible(true);if(!d.isOk())return;run(()->api.put("/api/visites/"+api.encode(o.codeMed())+"/"+api.encode(o.codePat())+"/"+o.date(),new Visite(d.med(),d.pat(),d.date(),"",""),Visite.class));}private void deleteRow(int row){Visite x=model.getAt(row);if(JOptionPane.showConfirmDialog(this,"Supprimer la visite du "+x.date()+" ?","Confirmation",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{api.delete("/api/visites/"+api.encode(x.codeMed())+"/"+api.encode(x.codePat())+"/"+x.date());return null;}protected void done(){try{get();refresh();status.setText("  Visite supprimée");}catch(Exception e){error(e);}}}.execute();}private interface Task{Object run()throws Exception;}private void run(Task t){new SwingWorker<Object,Void>(){protected Object doInBackground()throws Exception{return t.run();}protected void done(){try{get();refresh();status.setText("  Opération réalisée avec succès");}catch(Exception e){error(e);}}}.execute();}private void error(Exception e){Throwable x=e instanceof java.util.concurrent.ExecutionException&&e.getCause()!=null?e.getCause():e;status.setText("  Erreur : "+x.getMessage());JOptionPane.showMessageDialog(this,x.getMessage(),"Erreur",JOptionPane.ERROR_MESSAGE);}}
